def parser(log: str) -> dict[str, str]:
    import re
    import xml.etree.ElementTree as ET

    results: dict[str, str] = {}

    def normalize_tag(tag: str) -> str:
        return tag.split("}")[-1] if tag else ""

    def add_case(classname: str, name: str, status: str) -> None:
        if not name:
            return
        classname = (classname or "").strip()
        name = name.strip()
        key = f"{classname}::{name}" if classname else name
        rank = {"pass": 0, "skip": 1, "fail": 2}
        prev = results.get(key)
        if prev is None or rank[status] > rank[prev]:
            results[key] = status

    def status_from_case(case_elem) -> str:
        status_attr = (case_elem.attrib.get("status", "") or "").lower()
        result_attr = (case_elem.attrib.get("result", "") or "").lower()
        if status_attr in {"fail", "failed", "error"} or result_attr in {"fail", "failed", "error"}:
            return "fail"
        if status_attr in {"skip", "skipped"} or result_attr in {"skip", "skipped"}:
            return "skip"
        for child in case_elem:
            tag = normalize_tag(child.tag)
            if tag in {"failure", "error"}:
                return "fail"
            if tag == "skipped":
                return "skip"
        return "pass"

    def parse_testcase_tags(blob: str) -> None:
        testcase_pattern = re.compile(
            r'<testcase\b([^>/]*?)(?:>(.*?)</testcase>|/>)',
            re.DOTALL | re.IGNORECASE,
        )
        for match in testcase_pattern.finditer(blob):
            attrs = match.group(1) or ""
            inner = match.group(2) or ""
            attr_map = dict(re.findall(r'(\w+)="(.*?)"', attrs))
            name = attr_map.get("name", "")
            classname = attr_map.get("classname", "")
            status = "pass"
            status_attr = (attr_map.get("status", "") or "").lower()
            result_attr = (attr_map.get("result", "") or "").lower()
            if status_attr in {"fail", "failed", "error"} or result_attr in {"fail", "failed", "error"}:
                status = "fail"
            elif status_attr in {"skip", "skipped"} or result_attr in {"skip", "skipped"}:
                status = "skip"
            elif re.search(r'<(failure|error)\b', inner, re.IGNORECASE):
                status = "fail"
            elif re.search(r'<skipped\b', inner, re.IGNORECASE):
                status = "skip"
            add_case(classname, name, status)

    # Parse XML blocks (testsuite/testsuites)
    xml_block_pattern = re.compile(
        r'<testsuites\b[\s\S]*?</testsuites>|<testsuite\b[\s\S]*?</testsuite>',
        re.IGNORECASE,
    )
    for match in xml_block_pattern.finditer(log):
        xml_text = match.group(0)
        try:
            root = ET.fromstring(xml_text)
            for elem in root.iter():
                if normalize_tag(elem.tag) == "testcase":
                    classname = elem.attrib.get("classname", "")
                    name = elem.attrib.get("name", "")
                    add_case(classname, name, status_from_case(elem))
        except ET.ParseError:
            parse_testcase_tags(xml_text)

    # Fallback for truncated XML or logs without full blocks
    parse_testcase_tags(log)

    # Console output parsing fallbacks
    lines = log.splitlines()
    for line in lines:
        line = line.strip()

        # pytest style: file.py::test_name PASSED/FAILED/SKIPPED/ERROR
        m = re.match(r'^(?P<test>\S+::\S+)\s+(?P<status>PASSED|FAILED|SKIPPED|ERROR)\b', line)
        if m:
            status_map = {"PASSED": "pass", "FAILED": "fail", "ERROR": "fail", "SKIPPED": "skip"}
            add_case("", m.group("test"), status_map[m.group("status")])
            continue

        # unittest style: test_method (module.Class) ... ok/FAIL/ERROR/skipped
        m = re.match(
            r'^(?P<test>\w+)\s*\((?P<class>[^\)]+)\)\s*\.\.\.\s*(?P<status>ok|FAIL|ERROR|skipped)\b',
            line,
        )
        if m:
            status_map = {"ok": "pass", "FAIL": "fail", "ERROR": "fail", "skipped": "skip"}
            add_case(m.group("class"), m.group("test"), status_map[m.group("status")])
            continue

        # generic unittest: Class.test_method ... ok/FAIL/ERROR/skipped
        m = re.match(
            r'^(?P<test>[\w\.]+)\s+\.\.\.\s+(?P<status>ok|FAIL|ERROR|skipped)\b',
            line,
        )
        if m:
            status_map = {"ok": "pass", "FAIL": "fail", "ERROR": "fail", "skipped": "skip"}
            add_case("", m.group("test"), status_map[m.group("status")])
            continue

        # go test: --- PASS: TestName
        m = re.match(r'^---\s+(?P<status>PASS|FAIL|SKIP):\s+(?P<test>\S+)', line)
        if m:
            status_map = {"PASS": "pass", "FAIL": "fail", "SKIP": "skip"}
            add_case("", m.group("test"), status_map[m.group("status")])
            continue

        # jest: ✓ pass, ✕ fail, ○ skip
        m = re.match(r'^[✓✔]\s+(?P<test>.+)$', line)
        if m:
            add_case("", m.group("test"), "pass")
            continue
        m = re.match(r'^[✕✖]\s+(?P<test>.+)$', line)
        if m:
            add_case("", m.group("test"), "fail")
            continue
        m = re.match(r'^[○]\s+(?P<test>.+)$', line)
        if m:
            add_case("", m.group("test"), "skip")
            continue

        # jest summary: PASS/FAIL <test>
        m = re.match(r'^(PASS|FAIL)\s+(?P<test>.+)$', line)
        if m:
            add_case("", m.group("test"), "pass" if m.group(1) == "PASS" else "fail")
            continue

    return results
